from taf.collectors.core.entities.managed_ssh_connection import ManagedSshConnection,\
    PrivateKeyManagedSshConnection, KeyFetcherManagedSshConnection, ManagedKeyFetcher
from .factory import Factory


class ManagedSshConnectionFactoryBase(Factory):
    _mandatory_parameters = {"user", "host"}
    _optional_parameters = {"port", "channel_timeout"}

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(ManagedSshConnectionFactoryBase, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        if "proxy" in configuration:
            managed_ssh_connection = ManagedSshConnectionFactorySelector().create(
                configuration=configuration["proxy"],
                existing_arguments={})
            resulting_arguments["proxy"] = managed_ssh_connection


class ManagedSshConnectionFactory(ManagedSshConnectionFactoryBase):
    """
    Factory for managed SSH connections.
    """
    _optional_parameters = {"password"}
    _product_class = ManagedSshConnection


class PrivateKeyManagedSshConnectionFactory(ManagedSshConnectionFactoryBase):
    """
    Factory for privatekey managed SSH connections.
    """
    _mandatory_parameters = {"private_key"}
    _product_class = PrivateKeyManagedSshConnection


class KeyFetcherManagedSshConnectionFactory(ManagedSshConnectionFactoryBase):
    """
    Factory for keyfetcher managed SSH connections.
    """
    _product_class = KeyFetcherManagedSshConnection

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        super(KeyFetcherManagedSshConnectionFactory, self)._build_arguments(
            configuration=configuration,
            existing_arguments=existing_arguments,
            resulting_arguments=resulting_arguments)
        if "executor" in configuration["private_key"]:
            managed_ssh_connection = ManagedSshConnectionFactorySelector().create(
                configuration=configuration["private_key"].get("executor"),
                existing_arguments={})
        else:
            managed_ssh_connection = resulting_arguments["proxy"]
        resulting_arguments["managed_key_fetcher"] = ManagedKeyFetcher(
            managed_ssh_connection=managed_ssh_connection,
            target_host=configuration["private_key"].get("target_host", resulting_arguments["host"]),
            password=configuration["private_key"].get("password"),
            timeout=configuration["private_key"].get("timeout"))


class ManagedSshConnectionFactorySelector(Factory):
    """
    Factory selector class to get appropriate managed SSH connections.
    """

    def create(self, configuration, existing_arguments):
        factory_class = ManagedSshConnectionFactory
        if "private_key" in configuration:
            if isinstance(configuration["private_key"], dict):
                factory_class = KeyFetcherManagedSshConnectionFactory
            else:
                factory_class = PrivateKeyManagedSshConnectionFactory
        return factory_class().create(
            configuration=configuration,
            existing_arguments=existing_arguments)

